T[67] = { note = "她一开始不在。在下水道击败阿特雷克西斯后，清理东北角有市场摊位、带小型粉色召唤法阵的房间（不是阿特雷克西斯的大法阵）。随身带着达拉然之书的玩家点击该法阵，林恩就会从带栅栏的大圆门中走出。要获得这本书，在击杀阿鲁高后，从暗影獠牙城堡大法师阿鲁高房间的桌子上拾取黑色之书，再到银松森林琥珀磨坊后屋的蓝色水晶 Leyline Focus 使用它。", { "暗影箭雨", "暗影箭射向她30码内的所有人。" }, { "荆棘诅咒", "1.5秒施法：一个持续3分钟的诅咒，目标攻击时会偶尔受到伤害。移除它。" }, { "骷髅", "骷髅会爬起来并在她身旁战斗。杀掉它们。" } }
