T[69] = { { "捕网", "定身他身边所有人，持续10秒。" }, { "减速", "减慢一名玩家的攻击和移动速度，持续10秒，还可能将其击晕。" }, { "召唤机械蟑螂", "召唤机械蟑螂。他的“更新”会杀死蟑螂并为他治疗。" } }
T[70] = { note = "与爆破专家艾米·短芯交谈，并在她炸开两个洞穴入口时保护她。穿梭者会一波波涌来，随后格鲁比斯带着 Chomper 出现。" }
T[71] = { { "巨伏", "对他面前锥形范围内造成自然伤害（2秒施法）。只有坦克站在他面前。" }, { "连环闪电", "在附近玩家之间跳跃的闪电（2.5秒施法）。打断他。" } }
T[72] = { { "横扫人群", "打击他身边所有人并打断其施法。法师和治疗者保持距离。" }, { "弧形打击", "打击他面前锥形范围内的所有人。" }, { "践踏", "打击站在他身边的所有人。" } }
T[73] = { { "召唤火焰仆从", "战斗开始时召唤两名火焰仆从。" }, { "火球术", "他会保持距离施放此法术。打断他。" }, { "火焰之盾 II", "对他身边所有人造成火焰伤害，持续一分钟。牧师或萨满可以驱散它。" } }
T[74] = { { "行走炸弹", "他会逐个点亮房间四周的侏儒头像，每个头像都会放出行走炸弹，炸弹接触玩家后爆炸。头像旁边的按钮可以将其关闭。生命值低于一半时，他点亮得更快。" }, { "击退", "击退坦克。生命值低于一半时，会影响他周围的所有人。" } }
