T[76] = { { "统御意志", "控制一名非当前目标的玩家，持续15秒（2秒施法）。打断他，或者驱散玩家身上的效果。" }, { "暗影箭", "他会保持距离施放。打断他。" } }
T[77] = { { "呼唤援助", "你开打时，他会呼叫15码内的生物，包括他身边的两名 Razorfen Spearhide。战斗中要一直控制住其中一个。" }, { "雷霆一击", "每8到14秒：对他附近所有人造成自然伤害，并使他们的攻击和移动速度降低，持续10秒。" } }
T[78] = { { "旋风倾泻", "打击站在他附近的所有人。" }, { "荆棘光环", "任何攻击他或附近盟友（包括 主宰拉姆塔斯）的人都会受到自然伤害。" } }
T[79] = { note = "一道屏障封住了他的洞穴。杀掉站在前面的两名骷髅守卫：两个都死后屏障就会消失。", { "击溃", "每21到35秒，他会击中一名非当前目标的玩家，使其像死了一样倒地，无法攻击或施法。移动即可解除。" }, { "暴跳如雷", "每25到31秒：打击他附近所有人，并将其昏迷2.5秒。" }, { "狂怒", "生命值降到60%，然后40%时，他的攻击速度提高60%，攻击更猛，持续2分钟。" } }
T[80] = { note = "稀有蝙蝠，并非每次经过都会出现。出现时，它会在卡尔加·刺肋附近蝙蝠洞穴洞壁的一个小凹处等着。" }
T[81] = { { "闪电链", "她保持距离，一次又一次施放：一道最多弹到3名玩家的闪电（2.5秒施法）。打断她。" }, { "纯净术", "每9到15秒，她会免疫所有攻击和法术2秒。" }, { "恢复", "在15秒内治疗一名受伤的盟友或她自己。牧师或萨满可以移除它。" } }
T[82] = { { "召唤地行者", "一个地行者会跟随他，在他身旁战斗。" }, { "闪电箭", "他会保持距离施放。打断他。" }, { "逃跑求援", "生命值降到15%时，他会逃跑去求援。在他跑远前杀掉他。" } }
T[83] = { { "召唤地行者", "一个地行者会跟随他，在他身旁战斗。" }, { "闪电箭", "他会保持距离施放。打断他。" } }
T[84] = { { "暗言术：痛", "对其目标造成暗影伤害，每3秒一次，持续18秒。驱散魔法可以移除。" } }
T[85] = { note = "每三局左右，墓地的三个稀有精英之一会站在地图上六个位置中的一个：Azshir the Sleepless、Fallen Champion 或 Ironspine。", { "火焰的召唤", "60秒后对玩家造成暗影伤害（2秒施法）。法师或德鲁伊可以在此之前移除。" }, { "恐吓", "使一名玩家恐惧逃跑4秒。" }, { "灵魂虹吸", "生命值低于一半时，他会吸取一名玩家和离其最近的玩家，持续12秒，并治疗自己。" } }
T[86] = { note = "每三局左右，墓地的三个稀有精英之一会站在地图上六个位置中的一个：Azshir the Sleepless、Fallen Champion 或 Ironspine。", { "顺劈斩", "打击目标以及离目标最近的玩家。" }, { "斩杀", "重击生命值20%或更低的目标。让坦克保持在此之上。" } }
T[87] = { note = "每三局左右，墓地的三个稀有精英之一会站在地图上六个位置中的一个：Azshir the Sleepless、Fallen Champion 或 Ironspine。", { "虚弱诅咒", "降低30码内所有人造成的物理伤害，持续2分钟。法师或德鲁伊可以移除。" }, { "毒云术", "每5秒对附近所有人造成自然伤害，持续45秒。" } }
T[88] = { { "烈焰尖刺", "在玩家站的位置燃起一道火柱（3秒施法）：造成火焰伤害，之后9秒内每3秒再造成一次。离开火柱。" }, { "火焰新星", "对他10码内所有人造成火焰伤害。" }, { "烈焰震击", "对一名玩家造成火焰伤害，之后12秒内每3秒再造成一次。驱散魔法可以移除。" }, { "暗影箭", "他会保持距离施放。打断他。" } }
T[89] = { { "血色猎犬", "三条猎犬跟着他一起攻击，他还会给它们施放嗜血术。先杀掉它们。" }, { "嗜血术", "使他自己或一名盟友的攻击速度提高30%，持续30秒。牧师或萨满可以移除。" }, { "战斗怒吼", "提高他和猎犬的攻击强度，持续3分钟。" } }
